  `updated` int unsigned NOT NULL DEFAULT '0' COMMENT '最后修改',
  `state` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0:未使用; 1:使用中',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
